import os
from datetime import datetime
from taf.trafficgenerator.iperf import IperfFacade
from taf.ul.power_ue.devices.harmony import Harmony
from taf.ul.power_ue.devices.huawei.iperf_throughput_checker import (
    IperfThroughputChecker,
)
from taf.ul.power_ue.devices.device_class import PowerUeDevice
from taf.ul.power_ue.exception import (
    TrafficDirectionNotSupported,
    IperfThroughputCheckerNotExist,
    VerifyThroughputError,
    IperfVersionNotSupported,
    CheckUeIpFailedAfterAttach,
)


class HarmonyHonor(PowerUeDevice):

    """
    Huawei Harmony Honor UE
    """

    _DEFAULT_UI_VERSION = "HarmonyOS 3.0.0"

    def __init__(
        self, ue_config=None, tl=None, ui_version=None, robot_logs_dir=None, **kwargs
    ):
        super(HarmonyHonor, self).__init__(ue_config=ue_config, **kwargs)

        self.tl = tl
        self._ui_version = ui_version or self._DEFAULT_UI_VERSION
        self.robot_logs_dir = robot_logs_dir

        self._iperf_facades = {}
        self._iperf = None
        self._iperf_processes = {}

        self._iperf_throughput_checkers = {}

        self._harmony = Harmony(
            self._ui_version,
            ue_pc_ssh_config=self.ue_pc_ssh_config,
            ue_serial_number=self.ue_serial_number,
        )

    @property
    def appserver_ssh_config(self):
        return {
            "host": self.ue_config.iperf_details.ssh_connection_details.addr,
            "port": self.ue_config.iperf_details.ssh_connection_details.port,
            "username": self.ue_config.iperf_details.ssh_connection_details.username,
            "password": self.ue_config.iperf_details.ssh_connection_details.password,
        }

    @property
    def appserver_iperf_path(self):
        return self.ue_config.iperf_details.iperf_path

    @property
    def appserver_iperf_version(self):
        return self.iperf_version

    @property
    def ue_pc_ssh_config(self):
        return {
            "host": self.ue_config.ssh_connection_details.addr,
            "port": self.ue_config.ssh_connection_details.port,
            "username": self.ue_config.ssh_connection_details.username,
            "password": self.ue_config.ssh_connection_details.password,
        }

    @property
    def ue_serial_number(self):
        return self.ue_config.serial_number

    @property
    def ue_iperf_path(self):
        return self.ue_config.iperf_directory

    @property
    def ue_iperf_version(self):
        return self.iperf_version

    @property
    def iperf_version(self):
        version = self.ue_config.iperf_details.iperf_version
        major_version = int(version)
        if major_version not in [2, 3]:
            raise IperfVersionNotSupported(version)
        return major_version

    @property
    def iperf_details(self):
        return self.ue_config.iperf_details

    @property
    def ue_ip(self):
        return self._harmony.get_ue_ip()

    def prepare(self, **kwargs):
        self._harmony.setup()

    def teardown(self):
        self._harmony.teardown()
        super(HarmonyHonor, self).teardown()

    def attach(self, **kwargs):
        self._harmony.attach()

    def verify_attach(self, **kwargs):
        ue_ip = self._harmony.get_ue_ip()
        self.logger.info("verify attach get ue ip {}".format(ue_ip))
        if ue_ip in ["0.0.0.0", "127.0.0.1"]:
            raise CheckUeIpFailedAfterAttach(ue_ip)

    def detach(self, **kwargs):
        self._harmony.detach()

    def start_traffic(
        self,
        dt_name,
        direction,
        duration=10,
        throughput=10.0,
        protocol="udp",
        iperf_port=None,
        iperf_options=None,
        **kwargs
    ):

        self._iperf = IperfFacade()
        self._iperf_facades[dt_name] = self._iperf
        if not isinstance(duration, int):
            duration = int(duration)

        iperf_options = iperf_options or {}

        if dt_name in self._iperf_processes:
            self.logger.info("{} traffic is existed".format(dt_name))
            iperf_processes = self._iperf_processes[dt_name]
        else:
            iperf_processes = self._create_iperf_processes(
                dt_name=dt_name,
                direction=direction,
                throughput=throughput,
                duration=duration,
                protocol=protocol,
                iperf_port=iperf_port,
                iperf_options=iperf_options,
                **kwargs
            )
            self._iperf_processes[dt_name] = iperf_processes

        self._iperf.setup_iperfs(iperf_processes)
        self._iperf.start(iperf_processes, force_port_available=True)

    def _create_iperf_processes(
        self,
        dt_name,
        direction,
        throughput,
        duration,
        protocol,
        iperf_port,
        iperf_options,
        **kwargs
    ):

        if dt_name in self._iperf_throughput_checkers:
            iperf_throughput_checker = self._iperf_throughput_checkers[dt_name]
        else:
            iperf_throughput_checker = IperfThroughputChecker(self.logger)

        iperf_options["duration"] = duration
        iperf_options["protocol"] = protocol
        iperf_options["port"] = iperf_port
        iperf_options["throughput"] = "{}M".format(throughput)

        server_log_path = self._construct_log_path(
            self.robot_logs_dir, dt_name, direction, "server"
        )
        client_log_path = self._construct_log_path(
            self.robot_logs_dir, dt_name, direction, "client"
        )

        iperf_processes = []
        if direction == "ul":
            iperf_processes.append(
                self._create_iperf_server_on_appserver(
                    iperf_options, server_log_path, **kwargs
                )
            )
            iperf_processes.append(
                self._create_iperf_client_on_ue(
                    iperf_options, client_log_path, **kwargs
                )
            )

            version = (
                self.appserver_iperf_version
                if self.appserver_iperf_version == 3
                else ""
            )
            method_name = "create_iperf{}_throughput".format(version)
        elif direction == "dl":
            iperf_processes.append(
                self._create_iperf_server_on_ue(
                    iperf_options, server_log_path, **kwargs
                )
            )
            iperf_processes.append(
                self._create_iperf_client_on_appserver(
                    iperf_options, client_log_path, **kwargs
                )
            )

            version = self.ue_iperf_version if self.ue_iperf_version == 3 else ""
            method_name = "create_iperf{}_throughput".format(version)
        else:
            raise TrafficDirectionNotSupported(
                "{} direction is not supported".format(direction)
            )

        self._iperf_throughput_checkers[dt_name] = (
            iperf_throughput_checker,
            method_name,
            server_log_path,
            protocol,
            [0, duration],
        )

        return iperf_processes

    def _create_iperf_server_on_appserver(self, iperf_options, log_path, **kwargs):
        cmd_options = self._create_iperf_server_common_options(iperf_options)

        cmd_options["bind"] = self.iperf_details.network_interface_address

        return self._create_iperf_instance(
            cmd_options=cmd_options,
            iperf_path=self.appserver_iperf_path,
            host_configuration=self.appserver_ssh_config,
            log_path=log_path,
            version=self.appserver_iperf_version,
            mode="server",
        )

    def _create_iperf_client_on_ue(self, iperf_options, log_path, **kwargs):
        cmd_options = self._create_iperf_client_common_options(iperf_options)

        cmd_options["bind"] = self.ue_ip
        cmd_options["client"] = self.iperf_details.network_interface_address

        return self._create_iperf_instance(
            cmd_options=cmd_options,
            iperf_path=self.ue_iperf_path,
            host_configuration=self.ue_pc_ssh_config,
            log_path=log_path,
            adb=True,
            serial_number=self.ue_serial_number,
            version=self.ue_iperf_version,
            mode="client",
        )

    def _create_iperf_server_on_ue(self, iperf_options, log_path, **kwargs):
        cmd_options = self._create_iperf_server_common_options(iperf_options)

        cmd_options["bind"] = self.ue_ip

        return self._create_iperf_instance(
            cmd_options=cmd_options,
            iperf_path=self.ue_iperf_path,
            host_configuration=self.ue_pc_ssh_config,
            log_path=log_path,
            adb=True,
            serial_number=self.ue_serial_number,
            version=self.ue_iperf_version,
            mode="server",
        )

    def _create_iperf_client_on_appserver(self, iperf_options, log_path, **kwargs):
        cmd_options = self._create_iperf_client_common_options(iperf_options)

        cmd_options["bind"] = self.iperf_details.network_interface_address
        cmd_options["client"] = self.ue_ip

        return self._create_iperf_instance(
            cmd_options=cmd_options,
            iperf_path=self.appserver_iperf_path,
            host_configuration=self.appserver_ssh_config,
            log_path=log_path,
            version=self.appserver_iperf_version,
            mode="client",
        )

    def _create_iperf_client_common_options(self, iperf_options):
        cmd_options = {}
        cmd_options["udp"] = iperf_options["protocol"] == "udp"
        cmd_options["interval"] = (
            iperf_options.get("iperf_interval", None)
            or self.iperf_details.iperf_interval
        )
        cmd_options["port"] = iperf_options["port"]
        cmd_options["bandwidth"] = iperf_options["throughput"]
        cmd_options["time"] = iperf_options["duration"]
        cmd_options["len"] = (
            iperf_options.get("packet", None) or self.iperf_details.iperf_options.packet
        )

        cmd_options["format"] = "k"
        return cmd_options

    def _create_iperf_server_common_options(self, iperf_options):
        cmd_options = {}
        if self.iperf_version == 2:
            cmd_options["udp"] = iperf_options["protocol"] == "udp"
            cmd_options["len"] = (
                iperf_options.get("packet", None)
                or self.iperf_details.iperf_options.packet
            )

        cmd_options["format"] = "k"
        cmd_options["interval"] = (
            iperf_options.get("iperf_interval", None)
            or self.iperf_details.iperf_interval
        )
        cmd_options["port"] = iperf_options["port"]
        return cmd_options

    @staticmethod
    def _construct_log_path(log_dir, dt_name, direction, mode):
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        return os.path.join(
            log_dir, "{}_{}_{}_iperf_{}.txt".format(timestamp, dt_name, direction, mode)
        )

    def _create_iperf_instance(
        self,
        cmd_options,
        iperf_path,
        host_configuration,
        log_path,
        adb=False,
        serial_number="",
        version="",
        mode="client",
    ):
        version = version if str(version) == "3" else ""
        method_name = "create_iperf{version}_{mode}".format(version=version, mode=mode)
        self.logger.info(
            "create '{}' with options={} iperf_path={} adb={} serial_number={} host_configuration={} log_path={}".format(
                method_name,
                cmd_options,
                iperf_path,
                adb,
                serial_number,
                host_configuration,
                log_path,
            )
        )
        create_iperf_process_func = getattr(self._iperf, method_name)
        return create_iperf_process_func(
            cmd_options=cmd_options,
            iperf_path=iperf_path,
            adb=adb,
            serial_number=serial_number,
            host_configuration=host_configuration,
            log_path=log_path,
        )

    def stop_traffic(self, dt_name, **kwargs):
        iperf_facade = self._iperf_facades.get(dt_name, None)
        if not iperf_facade:
            self.logger.info("iperf facade for '{}' not existed".format(dt_name))
            return

        iperf_processes = self._iperf_processes.get(dt_name, None)
        if not iperf_processes:
            self.logger.info("iperf instance for '{}' not existed".format(dt_name))
            return

        iperf_facade.stop(iperf_processes)
        iperf_facade.teardown_iperfs()

    def check_unidirectional_throughput(
        self,
        dt_name,
        direction,
        theoretical_throughput,
        average_tolerance="0.95",
        minimum_tolerance="0.8",
        **kwargs
    ):

        average_tolerance = self._get_tolerance_decimal(tolerance=average_tolerance)
        minimum_tolerance = self._get_tolerance_decimal(tolerance=minimum_tolerance)

        return self._check_iperf_throughput(
            dt_name=dt_name,
            direction=direction,
            theoretical_throughput=theoretical_throughput,
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
        )

    def _get_airscale_cu_ssh_config(self, gnb_index, du_index, common_unit_index):

        host = self.tl.gnbs[gnb_index].dus[du_index].f1_m_ip_addr
        if not host:
            host = (
                self.tl.gnbs[gnb_index]
                .dus[du_index]
                .airscale.common_units[common_unit_index]
                .lmp_connection.addr
            )
        username = (
            self.tl.gnbs[gnb_index]
            .dus[du_index]
            .airscale.common_units[common_unit_index]
            .lmp_connection.username
        )
        password = (
            self.tl.gnbs[gnb_index]
            .dus[du_index]
            .airscale.common_units[common_unit_index]
            .lmp_connection.password
        )
        return host, username, password

    def _check_iperf_throughput(
        self,
        dt_name,
        direction,
        theoretical_throughput,
        average_tolerance,
        minimum_tolerance,
    ):
        if dt_name not in self._iperf_throughput_checkers:
            raise IperfThroughputCheckerNotExist

        (
            iperf_throughput_checker,
            method_name,
            file_path,
            protocol,
            time_range,
        ) = self._iperf_throughput_checkers[dt_name]
        self.logger.info(
            "iperf_throughput_checker.{} file_path={}, protocol={}, time_range={}".format(
                method_name, file_path, protocol, time_range
            )
        )
        create_throughput_func = getattr(iperf_throughput_checker, method_name)
        create_throughput_func(file_path, protocol, time_range)

        average_throughput = iperf_throughput_checker.get_average_throughput()
        self.logger.info("get average throughput {}".format(average_throughput))
        if average_throughput < average_tolerance:
            raise VerifyThroughputError(
                "average throughput {} is less than average tolerance throughput {}".format(
                    average_throughput, average_tolerance
                )
            )

        minimum_theoretical_throughput = (
            theoretical_throughput
            * self._get_tolerance_decimal(tolerance=minimum_tolerance)
        )

        statistics = iperf_throughput_checker.get_throughput_statistics()
        self.logger.info("get throughput statistics {}".format(statistics))
        minimum_throughput = self._calcullate_throughput_mbps_value(
            throughput=statistics["minimum_statistics"]
        )
        if minimum_throughput < minimum_theoretical_throughput:
            raise VerifyThroughputError(
                "get minimum throughput {} less than {}".format(
                    minimum_throughput, minimum_theoretical_throughput
                )
            )
        return statistics

    def reboot(self, **kwargs):
        pass

    def check_bidirectional_throughput(self, dt_name, **kwargs):
        raise NotImplementedError("Harmony do not support check bi direction traffic.")
